const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const wuhan = ee.Geometry.Polygon([
    [114.0, 30.8],
    [114.6, 30.8],
    [114.6, 30.4],
    [114.0, 30.4]
  ]);

  const period1 = ['2020-01-01', '2020-01-20']; // Before lockdown
  const period2 = ['2020-02-10', '2020-02-25']; // During lockdown

  // 2. Data Acquisition
  const no2Col = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .select('NO2_column_number_density');

  const col1 = no2Col.filterDate(period1[0], period1[1]).filterBounds(wuhan);
  const col2 = no2Col.filterDate(period2[0], period2[1]).filterBounds(wuhan);

  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`Jan 1-20 Images: ${size1}, Feb 10-25 Images: ${size2}`);

  // Check for empty collections
  if (size1 === 0 || size2 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Create mean composites
  const mean1 = col1.mean();
  const mean2 = col2.mean();

  // 3. Check valid pixels
  const count1 = mean1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: wuhan,
    scale: 1000,
    maxPixels: 1e9
  }).get('NO2_column_number_density').getInfo();

  const count2 = mean2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: wuhan,
    scale: 1000,
    maxPixels: 1e9
  }).get('NO2_column_number_density').getInfo();

  console.log(`Jan valid pixels: ${count1}, Feb valid pixels: ${count2}`);

  if (count1 === 0 || count2 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculate mean NO2 concentrations
  const no2_1 = mean1.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: wuhan,
    scale: 1000,
    maxPixels: 1e9
  }).get('NO2_column_number_density').getInfo();

  const no2_2 = mean2.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: wuhan,
    scale: 1000,
    maxPixels: 1e9
  }).get('NO2_column_number_density').getInfo();

  console.log(`Jan NO2: ${no2_1.toFixed(6)}, Feb NO2: ${no2_2.toFixed(6)}`);

  // 5. Validation & Final Answer
  if (no2_1 === null || no2_2 === null || isNaN(no2_1) || isNaN(no2_2)) {
    console.log("<answer>C3</answer>");
  } else if (no2_2 < no2_1) {
    console.log(`Decrease: ${((no2_1 - no2_2) / no2_1 * 100).toFixed(1)}%`);
    console.log("<answer>A</answer>");
  } else {
    console.log(`Change: ${((no2_2 - no2_1) / no2_1 * 100).toFixed(1)}%`);
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
